void mostrar(int* v, int n) {
 if (n == 0)
 return;
 cout << v[0] * v[0] << " ";
 mostrar(v + 1, n - 1);
}

int main() {
 int* v = new int[3];
 v[0] = 4;
 v[1] = 7;
 v[2] = 2;
 mostrar(v, 3);
 delete[] v;
 return 0;
}


 Qual será a saída do programa?
 a) 4 7 2
 b) 16 49 4
 c) 2 7 4
 d) Erro

